package pose
import("encoding/json";"os";"path/filepath";"testing";"os/exec")
func probeGraph(t *testing.T,s Store, change func(*DeliveryIntegrityGraph)) {t.Helper(); p:=filepath.Join(s.Root,".pose/indexes/delivery-integrity.json");b,e:=os.ReadFile(p);if e!=nil{t.Fatal(e)};var g DeliveryIntegrityGraph;if e=json.Unmarshal(b,&g);e!=nil{t.Fatal(e)};change(&g);b,_=json.Marshal(g);if e=os.WriteFile(p,b,0644);e!=nil{t.Fatal(e)}}
func TestB30R2ProbeMissingModule(t *testing.T){s:=factsFixture(t,"api",[]DeliveryValidationResult{{ID:"r",Check:"test",Outcome:"pass",ScopeProvenance:map[string]string{"alpha":"@scoped"}}},false);f,e:=s.DeriveSpecFacts("alpha");if e!=nil||len(f.Checks)!=1{t.Fatalf("not reproduced %+v %v",f,e)};t.Logf("REPRODUCED absent module associated: %+v",f.Checks)}
func TestB30R2ProbeEmptyScope(t *testing.T){s:=factsFixture(t,"api",nil,false);probeGraph(t,s,func(g *DeliveryIntegrityGraph){g.ChangeSets=nil;g.Claims=nil;g.ValidationResults=[]DeliveryValidationResult{{ID:"r",Module:"api",Check:"test",Outcome:"pass",ScopeProvenance:map[string]string{"alpha":ScopedDeliveryProvenanceDigest(*g,"alpha")}}}});f,e:=s.DeriveSpecFacts("alpha");if e!=nil||len(f.Checks)!=1{t.Fatalf("not reproduced %+v %v",f,e)};t.Logf("REPRODUCED empty scope associated: %+v limits=%v",f.Checks,f.Limitations)}
func TestB30R2ProbeDedup(t *testing.T){for _,reverse:=range []bool{false,true}{s:=factsFixture(t,"api",[]DeliveryValidationResult{{ID:"r",Module:"api",Check:"test",Outcome:"pass",ScopeProvenance:map[string]string{"alpha":"@scoped"}},{ID:"r",Module:"api",Check:"test",Outcome:"pass",ScopeProvenance:map[string]string{"alpha":"wrong"}}},false);if reverse{probeGraph(t,s,func(g *DeliveryIntegrityGraph){g.ValidationResults[0],g.ValidationResults[1]=g.ValidationResults[1],g.ValidationResults[0]})};f,e:=s.DeriveSpecFacts("alpha");if e!=nil||len(f.Checks)+len(f.Candidates)!=1{t.Fatalf("not reproduced %+v %v",f,e)};t.Logf("REPRODUCED reverse=%v associated=%d candidates=%d",reverse,len(f.Checks),len(f.Candidates))}}
func TestB30R2ProbeFreshResultsFields(t *testing.T){for _,field:=range []string{"git_head","scope_provenance","module","name","evidence_class","schema_version","new-results-empty-index"}{t.Run(field,func(t *testing.T){s:=factsFixture(t,"api",nil,false);policy:=filepath.Join(s.Root,".pose/policy/delivery.json");os.MkdirAll(filepath.Dir(policy),0755);os.WriteFile(policy,[]byte(`{"schema_version":1,"enabled":true,"adopted_at":"2026-08-04","results_path":".pose/results/delivery-validation.json","roots":[]}`),0644);p:=filepath.Join(s.Root,".pose/results/delivery-validation.json");os.MkdirAll(filepath.Dir(p),0755)
run:=map[string]any{"schema_version":1,"generated_at":"2026-10-18T00:00:00Z","git_head":"h1","provenance_digest":"global","scope_provenance":map[string]string{"alpha":"old"},"checks":[]map[string]any{{"id":"r","module":"api","name":"test","outcome":"pass","evidence_class":"unit"}}};probeGraph(t,s,func(g *DeliveryIntegrityGraph){if field!="new-results-empty-index"{g.ValidationResults=[]DeliveryValidationResult{{ID:"r",Module:"api",Check:"test",Outcome:"pass",EvidenceClass:"unit",GitHead:"h1",GeneratedAt:"2026-10-18T00:00:00Z",ProvenanceDigest:"global",ScopeProvenance:map[string]string{"alpha":"old"},Report:".pose/results/delivery-validation.json"}}}})
checks:=run["checks"].([]map[string]any);switch field{case "git_head":run[field]="h2";case "scope_provenance":run[field]=map[string]string{"alpha":"wrong"};case "schema_version":run[field]=999;case "module":checks[0][field]="web";case "name":checks[0][field]="other";case "evidence_class":checks[0][field]="integration"};b,_:=json.Marshal(run);os.WriteFile(p,b,0644);outputs:=map[string][]byte{};for _,n:=range IndexGenerationFiles{b,_:=os.ReadFile(filepath.Join(s.Root,".pose/indexes",n));if len(b)==0{b=[]byte("{}\n")};outputs[n]=b};if _,e:=s.PublishIndexGeneration(outputs,IndexInputBindings(s.Root));e!=nil{t.Fatal(e)};f,e:=s.DeriveSpecFacts("alpha");if e!=nil||f.Freshness.Status!=SpecFactsFresh{t.Fatalf("not reproduced %+v %v",f,e)};t.Logf("REPRODUCED %s freshness=%s results=%d",field,f.Freshness.Status,len(f.Checks)+len(f.Candidates))})}}
func TestB30R2ProbeTrailerWhitespace(t *testing.T){s:=factsFixture(t,"api",nil,true);git:=func(a ...string){t.Helper();c:=exec.Command("git",append([]string{"-C",s.Root,"-c","user.name=t","-c","user.email=t@t","-c","commit.gpgsign=false"},a...)...);if b,e:=c.CombinedOutput();e!=nil{t.Fatalf("%v %s",e,b)}};git("init","-q");os.WriteFile(filepath.Join(s.Root,".gitignore"),[]byte(".pose/\n"),0644);git("add",".gitignore");git("commit","-q","-m","later","-m","POSE-Spec:  alpha");f,e:=s.DeriveSpecFacts("alpha");if e!=nil||f.Freshness.Status!=SpecFactsFresh{t.Fatalf("not reproduced %+v %v",f,e)};t.Log("REPRODUCED whitespace trailer unindexed fresh")}
func TestB30R2ProbeRenames(t *testing.T){s:=factsFixture(t,"",nil,false);probeGraph(t,s,func(g *DeliveryIntegrityGraph){g.ChangeSets[0].Paths=[]ObservedPath{{Action:"renamed",OldPath:"api/old.go",NewPath:"api/new.go"},{Action:"renamed",OldPath:"web/old.js",NewPath:"web/new.js"}};g.ValidationResults=[]DeliveryValidationResult{{ID:"r",Module:"web",Check:"test",Outcome:"fail",ScopeProvenance:map[string]string{"alpha":ScopedDeliveryProvenanceDigest(*g,"alpha")}}}});f,e:=s.DeriveSpecFacts("alpha");if e!=nil||len(f.Paths)!=1||len(f.Candidates)!=1{t.Fatalf("not reproduced %+v %v",f,e)};t.Logf("REPRODUCED renames=%+v checks=%v candidates=%+v",f.Paths,f.Checks,f.Candidates)}
func TestB30R2ProbeOldRenameModule(t *testing.T){s:=factsFixture(t,"",nil,false);probeGraph(t,s,func(g *DeliveryIntegrityGraph){g.ChangeSets[0].Paths=[]ObservedPath{{Action:"renamed",OldPath:"api/old.go",NewPath:"web/new.go"}};g.ValidationResults=[]DeliveryValidationResult{{ID:"r",Module:"api",Check:"test",Outcome:"fail",ScopeProvenance:map[string]string{"alpha":ScopedDeliveryProvenanceDigest(*g,"alpha")}}}});f,e:=s.DeriveSpecFacts("alpha");if e!=nil||len(f.Candidates)!=1{t.Fatalf("not reproduced %+v %v",f,e)};t.Logf("REPRODUCED old module of rename excluded: %+v",f.Candidates)}
func TestB30R2ProbeOtherRef(t *testing.T){s:=factsFixture(t,"api",nil,true);git:=func(a ...string){t.Helper();c:=exec.Command("git",append([]string{"-C",s.Root,"-c","user.name=t","-c","user.email=t@t","-c","commit.gpgsign=false"},a...)...);if b,e:=c.CombinedOutput();e!=nil{t.Fatalf("%v %s",e,b)}};git("init","-q","-b","main");os.WriteFile(filepath.Join(s.Root,".gitignore"),[]byte(".pose/\n"),0644);git("add",".gitignore");git("commit","-q","-m","initial");git("checkout","-q","-b","other");git("commit","--allow-empty","-q","-m","other","-m","POSE-Spec: alpha");git("checkout","-q","main");f,e:=s.DeriveSpecFacts("alpha");if e!=nil||f.Freshness.Status!=SpecFactsFresh{t.Fatalf("not reproduced %+v %v",f,e)};t.Log("REPRODUCED new spec trailer on another ref absent from index still fresh")}
func TestB30R2ProbeDedupOtherFields(t *testing.T){for _,field:=range []string{"generated_at","evidence_class","provenance_digest"}{t.Run(field,func(t *testing.T){s:=factsFixture(t,"api",[]DeliveryValidationResult{{ID:"r",Module:"api",Check:"test",Outcome:"pass",ScopeProvenance:map[string]string{"alpha":"@scoped"}},{ID:"r",Module:"api",Check:"test",Outcome:"pass",ScopeProvenance:map[string]string{"alpha":"@scoped"}}},false);probeGraph(t,s,func(g *DeliveryIntegrityGraph){switch field{case "generated_at":g.ValidationResults[0].GeneratedAt="2026-10-18T00:00:00Z";g.ValidationResults[1].GeneratedAt="2026-10-18T01:00:00Z";case "evidence_class":g.ValidationResults[0].EvidenceClass="unit";g.ValidationResults[1].EvidenceClass="security-scan";case "provenance_digest":g.ValidationResults[0].ProvenanceDigest="old";g.ValidationResults[1].ProvenanceDigest="new"}});f,e:=s.DeriveSpecFacts("alpha");if e!=nil||len(f.Checks)!=1{t.Fatalf("not reproduced %+v %v",f,e)};t.Logf("REPRODUCED distinct %s collapsed",field)})}}
